<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserAcceptedTermsOfUse\Domain\ValueObject\UserAcceptedTermsOfUseConditionsVO;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\TenantTermsOfUseRef;

trait UserAcceptedTermsOfUseConditionsAccessor
{
    private UserAcceptedTermsOfUseConditionsVO $_conditions;
    public function getConditions(): TenantTermsOfUseRef
    {
        return $this->_conditions->value();
    }
    public function conditions(): UserAcceptedTermsOfUseConditionsVO
    {
        return $this->_conditions;
    }
    public function isConditionsChanged(?self $original = null): bool
    {
        return !$this->_conditions->equals($original?->_conditions);
    }
    public function withConditions(UserAcceptedTermsOfUseConditionsVO|TenantTermsOfUseRef $conditions): self
    {
        $copy = clone $this;
        $copy->_conditions = UserAcceptedTermsOfUseConditionsVO::from($conditions);
        return $copy;
    }
}
